Lemma pf_succ_old : forall p0 L vb p' nlen vptr vlen bsz, pf_succ p0 L vb p' nlen vptr vlen bsz ->
  p0 + 2 <= p' /\ p' + 1 <= L /\ 1 <= nlen /\ p0 + nlen < p' /\ ((p0 <= vptr /\ 0 <= vlen /\ vptr + vlen <= L) \/ (vptr = vb /\ vlen = bsz)).
Proof. intros * PS. unfold pf_succ in PS. repeat match goal with H : _ /\ _ |- _ => destruct H end. repeat split; try lia. Qed.

