Definition ipf_pure (sp : word) (P IN E lo : Z) (c : pcore) (p0 : Z) (bs : list byte) : Prop :=
  pcore_ok c /\ lo + 4800 <= bv_unsigned sp /\ 0xb8000 <= lo
  /\ ((0 < p0 /\ p0 + Z.of_nat (length bs) <= 0x10000) \/ 0xb8000 <= p0) /\ p0 + Z.of_nat (length bs) <= lo /\ Z.of_nat (length bs) <= 8194
  /\ bv_unsigned sp <= P /\ P + 256 <= 2^64 /\ bv_unsigned sp <= IN /\ IN + 8 <= 2^64 /\ bv_unsigned sp <= E /\ E + 24 <= 2^64
  /\ (P + 256 <= IN \/ IN + 8 <= P) /\ (P + 256 <= E \/ E + 24 <= P) /\ (IN + 8 <= E \/ E + 24 <= IN)
  /\ E mod 8 = 0 /\ bv_unsigned sp mod 16 = 0.                                 (* [comment removed for export] *)

(* [comment removed for export] *)
Definition ipf_frame (m1 : mem) (sp : word) (j16 jt : list byte) (p bsz : Z) (bb : list byte) (vl nm : list cell) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -4288) [CB 16 j16]
  /\ rw_cells usegs m1 (bv_unsigned sp + -4272) [CB 24 jt]
  /\ rw_cells usegs m1 (bv_unsigned sp + -4248) [C8 (wz p)]
  /\ rw_cells usegs m1 (bv_unsigned sp + -4240) [C8 (wz bsz); CB 4096 bb] /\ 0 <= bsz <= 4096
  /\ rw_cells usegs m1 (bv_unsigned sp + -136) vl /\ cells_size vl = 16%nat
  /\ rw_cells usegs m1 (bv_unsigned sp + -120) nm /\ cells_size nm = 16%nat.

