(* [comment removed for export] *)

(* [comment removed for export] *)

Definition ipf_ret_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (qlo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (q : Z) (E' : ecv) (c' : pcore) (g' : bool),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (ipf_W lo sp P IN E) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' P (ParserCoreCells c' pad7 pad2) /\ dof_core c c'
    /\ rw_cells usegs m' IN [C8 (wz q)] /\ p0 <= q <= p0 + Z.of_nat (length bs) /\ qlo <= q
    /\ rw_cells usegs m' E (ErrCodeCells E') /\ (E' = EC_clear \/ http_fail E') /\ (E' = EC_clear -> p0 + 2 <= q)
    /\ bytes_at usegs m' p0 bs /\ PfTab m' /\ (FieldTabZero m' \/ FT m')
    /\ HttpCat m' g' /\ XStatics m'.

(* [comment removed for export] *)
Definition ipf_ctx (m m1 : mem) (sp : word) (sv : list word) (P IN E lo : Z) (c1 : pcore) (pad7 pad2 : list byte)
    (p0 : Z) (bs : list byte) (q : Z) (E1 : ecv) (g : bool) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -104) (map C8 sv)
  /\ rw_cells usegs m1 P (ParserCoreCells c1 pad7 pad2)
  /\ rw_cells usegs m1 IN [C8 (wz q)]
  /\ rw_cells usegs m1 E (ErrCodeCells E1)
  /\ bytes_at usegs m1 p0 bs /\ PfTab m1 /\ (FieldTabZero m1 \/ FT m1)
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk usegs m1 lo (bv_unsigned sp + -4288)
  /\ munch (ipf_W lo sp P IN E) m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.

End HCW.

(* [comment removed for export] *)
Ltac ipf_open CTX PURE sp :=
  pose proof PURE as PURE0;
  destruct CTX as (FRhi & PC & IT & EC & WIN & PFT & FTS & HC & XS & ST & MU & WM & MI);
  destruct PURE as (PCOK & LO & IMG & QLO & QHI & LBS & PLO & PHI & ILO & IHI & ELO & EHI & DPI & DPE & DIE & EAL & SPAL);
  apply uhide_i in EAL; apply uhide_i in SPAL;
  pose proof PCOK as PCOK0; destruct PCOK as (Bh & Bl & Ln & Ln0 & Sk & Hl & Stt & Ff);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold ipf_W, G_HTTP_CAT, G_FIELD_TABLE in *; unfold ipf_sv in FRhi; cbn [map] in FRhi;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  unfold PfTab, PF_TABPTR, PF_TAB in PFT;
  unfold wz in *.

(* [comment removed for export] *)
Ltac ipf_ctx_close :=
  unfold ipf_ctx, ipf_sv, ipf_W, G_HTTP_CAT, G_FIELD_TABLE, ParserCoreCells, PfTab, PF_TABPTR, PF_TAB; cbn [map pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f]; unfold wz;
  repeat match goal with |- _ /\ _ => split end; try fast_eassumption.
Ltac ipf_frame_close :=
  unfold ipf_frame; unfold wz; repeat match goal with |- _ /\ _ => split end; try fast_eassumption; try reflexivity; try lia.

Section HCW2.
  Context {HCEIL : HeapCeil}.
  (* [comment removed for export] *)
  Hypothesis DOF : dof_stmt.

(* [comment removed for export] *)
Definition ipf_plainret_stmt : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s4x s5x s6x s7x s8x s9x s10x s11x
         s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (q : Z) (E1 : ecv) (g : bool) (j16 jt : list byte) (p bsz : Z) (bb : list byte) (vl nm : list cell),
  ipf_ctx m m1 sp (ipf_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo c1 pad7 pad2 p0 bs q E1 g ->
  ipf_frame m1 sp j16 jt p bsz bb vl nm ->
  ipf_pure sp P IN E lo c p0 bs -> dof_core c c1 -> p0 <= q <= p0 + Z.of_nat (length bs) -> http_fail E1 ->
  evt usegs (ipf_ret_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo c pad7 pad2 p0 bs q m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -4288)) gp tp t0 t1 t2 (wz E) (wz IN) a0 a1 a2 a3 a4 a5 a6 a7
              s2x (wz P) s4x s5x s6x s7x s8x s9x s10x s11x t3 t4 t5 t6)
        F (Z_to_bv 64 IPF_EPI) fc None m1 (seg_rom usegs)).

