Scheme kc__3 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

(* [comment removed for export] *)
Lemma ipf_done_tail : forall rax ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s0x s2x s3x s4x s5x s6x s7x s8x s9x s10x s11x
         s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (IN lo : Z) (q p : Z) (j16 : list byte) (tmp : list cell) (bsz : Z) (bb : list byte) (vl nm : list cell),
  rw_cells usegs m1 (bv_unsigned sp + -4288) [CB 16 j16] ->
  rw_cells usegs m1 (bv_unsigned sp + -4272) tmp -> cells_size tmp = 24%nat ->
  rw_cells usegs m1 (bv_unsigned sp + -4248) [C8 (wz p)] ->
  rw_cells usegs m1 (bv_unsigned sp + -4240) [C8 (wz bsz); CB 4096 bb] -> 0 <= bsz <= 4096 ->
  rw_cells usegs m1 (bv_unsigned sp + -136) vl -> cells_size vl = 16%nat ->
  rw_cells usegs m1 (bv_unsigned sp + -120) nm -> cells_size nm = 16%nat ->
  rw_cells usegs m1 (bv_unsigned sp + -104) (map C8 (ipf_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra)) ->
  rw_cells usegs m1 IN [C8 (wz q)] ->
  stk usegs m1 lo (bv_unsigned sp + -4288) -> 0 <= lo -> lo <= bv_unsigned sp + -4288 -> bv_unsigned sp <= IN -> IN + 8 <= 2^64 ->
  0 < p -> p + 2 < 2^64 -> mem_inv usegs m1 ->
  evt usegs (fun ms' => exists t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
      ms' = MS (mkR ra sp gp tp t0' t1' t2' s0v s1v a0' a1' a2' a3' a4' a5' a6' a7' s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3' t4' t5' t6')
               F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ munch [(IN, IN + 8)]%Z m1 m' /\ wmono usegs m1 m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' IN [C8 (wz (p + 2))])
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -4288)) gp tp t0 t1 t2 s0x (wz IN) (wz p) a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5x s6x s7x s8x s9x s10x s11x t3 t4 t5 t6)
