(* [comment removed for export] *)
Definition ipf_slot_target (st : Z) : Z := if st =? 10 then VS_PARSER_40 else VS_PARSER_32.

(* [comment removed for export] *)
Definition ipf_vcall_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (q p : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 t3 t4 t5 t6 m' (c2 : pcore) (g' : bool) (p' f nlen vptr vlen bsz : Z) (nbs vbs j16 jt bb : list byte),
    ms' = MS (mkR (wz IPF_VRET) (Z_to_bv 64 (bv_unsigned sp + -4288)) gp tp t0 t1 t2 (wz E) (wz IN)
                  (wz P) (wz f) (wz p) (wz nlen) (wz vptr) (wz vlen) (wz E) (wz (ipf_slot_target (pc_state c)))
                  (wz (p0 + Z.of_nat (length bs))) (wz P) (wz G_FIELD_TABLE_GUARD) (wz G_FIELD_TABLE) (wz f) (wz nlen)
                  (Z_to_bv 64 (bv_unsigned sp + -128)) (wz 2) (wz 1) (wz 10) t3 t4 t5 t6)
             F (wz (ipf_slot_target (pc_state c))) fc None m' (seg_rom usegs)
    /\ munch (ipf_W lo sp P IN E) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -4288)
    /\ ipf_frame m' sp j16 jt p' bsz bb [C8 (wz vptr); C8 (wz vlen)] [C8 (wz p); C8 (wz nlen)]
    /\ rw_cells usegs m' (bv_unsigned sp + -104) (map C8 (ipf_sv s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra))
    /\ rw_cells usegs m' P (ParserCoreCells c2 pad7 pad2) /\ dof_core c c2 /\ (pc_state c = 10 -> c2 = c)
    /\ rw_cells usegs m' IN [C8 (wz q)]
    /\ rw_cells usegs m' E (ErrCodeCells EC_clear)
    /\ bytes_at usegs m' p0 bs /\ PfTab m' /\ FT m' /\ FTInit m'
    /\ HttpCat m' g' /\ XStatics m'
    /\ bytes_at usegs m' p nbs /\ Z.of_nat (length nbs) = nlen /\ f = ft_lookup (zbytes nbs)
    /\ bytes_at usegs m' vptr vbs /\ Z.of_nat (length vbs) = vlen
    /\ pf_succ p (p0 + Z.of_nat (length bs)) (bv_unsigned sp + -4232) p' nlen vptr vlen bsz.

Definition ipf_segA_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (q p : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => ipf_ret_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs q m ms'
          \/ ipf_vcall_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs q p m ms'.

(* [comment removed for export] *)
Lemma ipf_vc : forall rax ra sp gp tp t0 t1 t2 a1 a2 a3 a6 a7 s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c c2 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (q p p' f nlen vptr vlen bsz : Z) (nbs vbs j16 jt bb : list byte) (g : bool),
  ipf_ctx m m1 sp (ipf_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo c2 pad7 pad2 p0 bs q EC_clear g ->
  FT m1 -> FTInit m1 ->
  ipf_frame m1 sp j16 jt p' bsz bb [C8 (wz vptr); C8 (wz vlen)] [C8 (wz p); C8 (wz nlen)] ->
  ipf_pure sp P IN E lo c p0 bs -> dof_core c c2 -> (pc_state c = 10 -> c2 = c) ->
  bytes_at usegs m1 p nbs -> Z.of_nat (length nbs) = nlen -> f = ft_lookup (zbytes nbs) ->
  bytes_at usegs m1 vptr vbs -> Z.of_nat (length vbs) = vlen ->
  pf_succ p (p0 + Z.of_nat (length bs)) (bv_unsigned sp + -4232) p' nlen vptr vlen bsz ->
  evt usegs (ipf_segA_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo c pad7 pad2 p0 bs q p m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -4288)) gp tp t0 t1 t2 (wz E) (wz IN)
              (wz (if pc_state c =? 10 then 40 else 32)) a1 a2 a3 (wz vptr) (wz vlen) a6 a7
              (wz (p0 + Z.of_nat (length bs))) (wz P) (wz G_FIELD_TABLE_GUARD) (wz G_FIELD_TABLE) (wz f) (wz nlen)
              (Z_to_bv 64 (bv_unsigned sp + -128)) (wz 2) (wz 1) (wz 10) t3 t4 t5 t6)
