(* [comment removed for export] *)
Lemma ipf_dof : forall rax ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s6x s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (q p p' f nlen vptr vlen bsz : Z) (nbs vbs j16 jt bb : list byte) (g : bool),
  ipf_ctx m m1 sp (ipf_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo c pad7 pad2 p0 bs q EC_clear g ->
  FT m1 -> FTInit m1 ->
  ipf_frame m1 sp j16 jt p' bsz bb [C8 (wz vptr); C8 (wz vlen)] [C8 (wz p); C8 (wz nlen)] ->
  ipf_pure sp P IN E lo c p0 bs -> p0 <= q <= p0 + Z.of_nat (length bs) ->
  bytes_at usegs m1 p nbs -> Z.of_nat (length nbs) = nlen -> f = ft_lookup (zbytes nbs) ->
  bytes_at usegs m1 vptr vbs -> Z.of_nat (length vbs) = vlen ->
  p0 <= p -> pf_succ p (p0 + Z.of_nat (length bs)) (bv_unsigned sp + -4232) p' nlen vptr vlen bsz ->
  evt usegs (ipf_segA_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo c pad7 pad2 p0 bs q p m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -4288)) gp tp t0 t1 t2 (wz E) (wz IN)
              (wz f) a1 a2 a3 a4 a5 a6 a7
              (wz (p0 + Z.of_nat (length bs))) (wz P) (wz G_FIELD_TABLE_GUARD) (wz G_FIELD_TABLE) s6x (wz nlen)
              (Z_to_bv 64 (bv_unsigned sp + -128)) (wz 2) (wz 1) (wz 10) t3 t4 t5 t6)
